import { Action, Flow, RetryPolicy } from "@smthrs/flow";
import { Inbox } from "@smthrs/notifications";
import { Node, Placement } from "@smthrs/plan";
import { Schema } from "effect";
import { MAX_SUBJECT_LENGTH } from "./contract";
// The feed's acts, as flows (decision 0009 decision 10, docs/features/notifications.md#flows):
//
//   watch/set { conversationId }            a tab shows a conversation: follow its branch and repository
//     watch/set/request ─ POST /api/watches
//
//   notification/ack { subject, version, act }   Read, Dismiss or Hide, from the stack or the list
//     notification/ack/request ─ POST /api/notifications/ack
//
// Each step tries again while ChatApi can't be reached, for a day, so an act taken offline lands once the device is
// back; a refusal is final. ChatApi merges an act with `greatest()`, so sending it twice changes nothing. What the steps
// do is steps.ts, which only an engine's host imports.
/** ChatApi refused the act (`status`, a 4xx): it can't land, so it isn't tried again. */
export class ActRefused extends Schema.TaggedError()("@smthrs/mvp/attention/ActRefused", {
    status: Schema.Number,
}) {
}
/** ChatApi couldn't be reached, or failed: tried again. Its client's span has the HTTP status. */
export class ActUnsent extends Schema.TaggedError()("@smthrs/mvp/attention/ActUnsent", {}) {
}
/** What an act can fail with. */
export const ActFailure = Schema.Union([ActRefused, ActUnsent]);
/** 500 ms doubling to 30 s, for a day: an act taken offline lands once the device is back. A refusal is final. */
export const ACT_RETRY = RetryPolicy.make({
    initialMs: 500,
    factor: 2,
    maxMs: 30_000,
    expirationMs: 24 * 60 * 60 * 1000,
    nonRetryable: ["@smthrs/mvp/attention/ActRefused"],
});
const watchPayload = { conversationId: Schema.NullOr(Schema.String.check(Schema.isUUID())) };
const ackPayload = {
    subject: Schema.String.check(Schema.isBetweenLength(1, MAX_SUBJECT_LENGTH)),
    version: Schema.Int.check(Schema.isGreaterThan(0)),
    act: Inbox.Act,
};
/** The step: ask ChatApi to follow the conversation's branch and repository. */
export const WatchRequestStep = Action.make("watch/set/request", {
    payload: watchPayload,
    success: Schema.Struct({ watching: Schema.Boolean }),
    error: ActFailure,
    retryPolicy: ACT_RETRY,
});
/** `watch/set`: follow the branch and repository of a conversation. */
export const WatchSet = Flow.make("watch/set", {
    description: "Follow the branch and the repository of a conversation: runs on that branch, and the repository's " +
        "main moving and new releases, reach your notifications. conversationId null is the home conversation.",
    modelInvocable: true,
    payload: watchPayload,
    success: Schema.Struct({ watching: Schema.Boolean }),
    error: ActFailure,
    body: Node.capture({ action: WatchRequestStep.name }, (request) => WatchRequestStep.call(request)),
}).annotate(Flow.Placement, Placement.client());
/** The step: ask ChatApi to record the act. */
export const AckRequestStep = Action.make("notification/ack/request", {
    payload: ackPayload,
    success: Schema.Struct({ recorded: Schema.Boolean }),
    error: ActFailure,
    retryPolicy: ACT_RETRY,
});
/** `notification/ack`: the person read, dismissed or hid one of their notifications. */
export const Ack = Flow.make("notification/ack", {
    description: "Record that the person read, dismissed or hid one of their notifications, at the version they saw.",
    modelInvocable: false,
    payload: ackPayload,
    success: Schema.Struct({ recorded: Schema.Boolean }),
    error: ActFailure,
    body: Node.capture({ action: AckRequestStep.name }, (request) => AckRequestStep.call(request)),
}).annotate(Flow.Placement, Placement.client());
